mapper.select:
        SELECT


--         级联表的字段
        ,assessment_question.content as questionContent
        ,assessment_question.options as questionOptions
        ,assessment_question.score as questionScore
        ,assessment_question.answer as questionAnswer
        ,assessment_question.analysis as questionAnalysis
        ,assessment_question.question_type as questionType
        ,assessment_question.sort_order as questionSortOrder
        ,student.name as studentName
        ,student.phone as studentPhone
        ,student.id_card_no as studentIdCardNo
        ,student.avatar_url as studentAvatarUrl
        ,student.email as studentEmail

        FROM assessment_answer  a
        left JOIN assessment_question assessment_question ON a.question_id = assessment_question.id
        left JOIN student student ON a.student_id = student.id



                and a.id in

                #{item}



                and a.record_no like CONCAT('%',#{params.recordNo},'%')


                and (
                    a.student_id = #{params.studentId}
                )


                and (
                    a.question_id = #{params.questionId}
                )


                and a.student_answer like CONCAT('%',#{params.studentAnswer},'%')


                  and a.score >= #{params.examredetailsMyscoreStart}   


                  and a.score <= #{params.examredetailsMyscoreEnd}   


                and a.score = #{params.score}




                and a.question_id IS NOT NULL


                and assessment_question.paper_id = #{params.paperId}


                and assessment_question.content like CONCAT('%',#{params.questionContent},'%')


                and assessment_question.options like CONCAT('%',#{params.questionOptions},'%')


                  and assessment_question.score >= #{params.examquestionScoreStart}   


                  and assessment_question.score <= #{params.examquestionScoreEnd}   


                and assessment_question.score = #{params.questionScore}


                and assessment_question.answer like CONCAT('%',#{params.questionAnswer},'%')


                and assessment_question.analysis like CONCAT('%',#{params.questionAnalysis},'%')


                and assessment_question.question_type = #{params.questionType}



                  and assessment_question.sort_order >= #{params.examquestionSequenceStart}   


                  and assessment_question.sort_order <= #{params.examquestionSequenceEnd}   


                and assessment_question.sort_order = #{params.questionSortOrder}



                and a.student_id IS NOT NULL


                and student.name like CONCAT('%',#{params.studentName},'%')


                and student.phone like CONCAT('%',#{params.studentPhone},'%')


                and student.id_card_no like CONCAT('%',#{params.studentIdCardNo},'%')


                and student.email like CONCAT('%',#{params.studentEmail},'%')



        order by a.${params.orderBy} desc
